async function load(setState) {
  setState({ status: "loading" });
  try {
    const res = await fetch("/api/items");
    if (!res.ok) throw new Error("Failed");
    setState({ status: "success", data: await res.json() });
  } catch (e) {
    setState({ status: "error", message: e.message });
  }
}

